// Code Lab 2.0's charts: the Vega and Vega-Lite browser builds (BSD-3), plus Vega's expression interpreter, as text to put
// into a widget frame. Kept in their own module so the app loads them (about 790 KB) only when a page has a chart:
// widget.ts imports this lazily. The export viewer inlines it, so exported pages draw charts offline.
// Order matters: Vega-Lite's build and the interpreter both read window.vega. The interpreter is needed because the
// frame's Content-Security-Policy blocks eval, which Vega otherwise uses for chart formulas (shared/vega-interpreter.js,
// generated by scripts/vendor-vega.mjs).
// Imported by file path: the packages' "exports" field doesn't expose their browser builds.
import vegaJs from "../../../../node_modules/vega/build/vega.min.js?raw";
import vegaLiteJs from "../../../../node_modules/vega-lite/build/vega-lite.min.js?raw";
import interpreterJs from "../../../../shared/vega-interpreter.js?raw";

export const VEGA_SOURCES = [vegaJs, vegaLiteJs, interpreterJs];
